<template>
  <el-card>
    <h1 class="me-author-name">卫星地面融合网络社区</h1>
    <div class="me-community-description">
      <p class="me-community-mission">
        <i class="el-icon-target"></i> &nbsp;社区宗旨：促进卫星与地面网络融合技术的交流与发展
      </p>
      <p class="me-community-goal">
        <i class="el-icon-star-on"></i> &nbsp;社区目标：构建专业的卫星网络技术交流平台
      </p>
      <p class="me-community-intro">
        <i class="el-icon-info"></i> &nbsp;社区简介：为卫星地面融合网络发烧友提供技术分享、问题讨论和资源共享的空间
      </p>
    </div>
    <div class="me-community-features">
      <el-tag size="small" type="primary">技术分享</el-tag>
      <el-tag size="small" type="success">问题讨论</el-tag>
      <el-tag size="small" type="warning">资源共享</el-tag>
      <el-tag size="small" type="info">行业动态</el-tag>
    </div>
  </el-card>

</template>

<script>
  export default {
    name: 'CardMe',
    data() {
      return {
      }
    }
  }
</script>

<style scoped>
  .me-author-name {
    text-align: center;
    font-size: 20px;
    border-bottom: 1px solid var(--primary-color);
    color: var(--secondary-color);
    padding-bottom: 10px;
    margin-bottom: 15px;
  }

  .me-community-description {
    padding: 10px 0;
  }

  .me-community-mission,
  .me-community-goal,
  .me-community-intro {
    margin-bottom: 8px;
    font-size: 14px;
    line-height: 1.5;
  }

  .me-community-features {
    margin-top: 15px;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .el-tag {
    margin-bottom: 8px;
  }
</style>



